  if (req.script) {
    const faux = fauxProvider(); models.setProvider(faux.provider); provider = 'faux'; modelId = 'faux-1';
    faux.setResponses(req.script.map(step => async (ctx) => {
      captured.push(ctx);
      if (step.delayMs) await new Promise(resolve => setTimeout(resolve, step.delayMs));
      return step.error ? fauxAssistantMessage('', { stopReason: 'error', errorMessage: step.error })
        : step.tool ? fauxAssistantMessage(fauxToolCall(step.tool, step.args ?? {}), { stopReason: 'toolUse' })
        : fauxAssistantMessage(step.text ?? 'Done');
    }));
  } else if (req.mode !== 'inspect') {
    if (!models.getProvider(provider)) throw new Error(`Unknown Pi AI provider: ${provider}`);
    const model = models.getModel(provider, req.model);
    if (model && !getSupportedThinkingLevels(model).includes(req.reasoning)) {
      throw new Error(`Model ${req.model} does not support reasoning ${req.reasoning}; choose ${getSupportedThinkingLevels(model).join(', ')}`);
    }
    provisionalModel = registerUnlistedModel(models, provider, req.model, req.reasoning);
    if (provisionalModel) console.log(`Model ${provider}/${req.model} is unlisted; trying the exact ID with provisional metadata. Cost estimates unavailable.`);
  }
  let root: Conversation;
  let minEntryId: number | undefined;
  let checkpointAt = Date.now();
  const endOfIteration = () => Math.min(Date.now() + req.seconds * 1000, req.deadline ? Date.parse(req.deadline) : Infinity);
  let iterationEndsAt = endOfIteration();
  const instructions = req.checkpointSeconds === 0
    ? `${INSTRUCTIONS} Automatic task checkpoints are disabled. Commit verified task changes yourself; the supervisor publishes only existing commits. Uncommitted task edits do not survive the next iteration.`
    : INSTRUCTIONS;
  const updateTime = () => root.configure({ instructions: `${instructions}\n\n${timeRemainingInstructions(iterationEndsAt, req.deadline, Date.now(), req.checkpointSeconds || 300)}` }, context);
  async function checkpoint(force = false) {
    // Zero disables every automatic checkpoint, including the session-start boundary.
    if (!req.checkpointHandshake || req.checkpointSeconds === 0 || (!force && (!req.checkpointSeconds || Date.now() - checkpointAt < req.checkpointSeconds * 1000))) return;
    const nonce = `${Date.now()}`;
    await updateTime();
    const maxEntryId = await snapshotJournal(root, journal, req.output, context);
    await json(join(req.output, 'checkpoint.json'), { nonce, id: req.id, minEntryId, maxEntryId,
      at: new Date().toISOString(), phase: force ? 'started' : 'tools' });
    // Stay cooperatively at this boundary until the supervisor publishes the prepared snapshot.
    for (let n = 0; n < 240; n++) {
      try { if ((await readFile(join(req.output, 'checkpoint.ack'), 'utf8')).trim() === nonce) { checkpointAt = Date.now(); return; } } catch {}
